import { expect, test } from "vitest";
import { checkPat, fillToken, PLACEHOLDER } from "../patToken";

// generated by aidoc.mcp.tokens.generate_token()
const GOOD = ["doc4ai_pat_xGW2n8zGcJdieMqBmDCjiu10YwpYVPWuO187gPXtTYj_450QG8", "doc4ai_pat_WBd1ELQU8QrZdvkhpRMN1IoGFgJ7CYs9R8xhcmak6kd_1Vbt9Y"];

test("well-formed tokens pass, including the CRC32 checksum", () => {
  for (const t of GOOD) expect(checkPat(t)).toBe("ok");
  expect(checkPat(`  ${GOOD[0]}\n`)).toBe("ok"); // pasted with whitespace
});

test("empty, non-PAT strings and damaged PATs are told apart", () => {
  expect(checkPat("")).toBe("empty");
  expect(checkPat("   ")).toBe("empty");
  expect(checkPat("s3cret-server-token")).toBe("not_pat"); // e.g. the aidoc serve --token value
  expect(checkPat(`Bearer ${GOOD[0]}`)).toBe("bearer");
  expect(checkPat(GOOD[0].slice(0, -1))).toBe("malformed"); // cut short
  expect(checkPat(GOOD[0].replace("_450QG8", "-450QG8"))).toBe("malformed");
  expect(checkPat(GOOD[0].replace("xGW2", "xGW3"))).toBe("checksum");
});

test("fillToken replaces every placeholder", () => {
  expect(fillToken(`a ${PLACEHOLDER} b ${PLACEHOLDER}`, "T")).toBe("a T b T");
  expect(fillToken("no placeholder", "T")).toBe("no placeholder");
});
